const item = $input.first();
const body = item?.json?.body || item?.json || {};
const binary = item?.binary || {};
const fileKey = binary.file ? 'file' : Object.keys(binary)[0] || '';
const hasText = Boolean(String(body.text || body.content || body.referenceText || body.fileText || '').trim());
const filename = fileKey ? String(binary[fileKey]?.fileName || body.filename || body.title || '') : '';
const extension = filename.includes('.') ? filename.split('.').pop().toLowerCase() : String(body.sourceType || '').toLowerCase();
return [{ json: {
  body,
  fileKey,
  filename,
  extension,
  uploadMode: hasText ? 'text' : fileKey ? 'file' : 'missing'
}, binary }];

const body = $json.body || {};
const text = String(body.text || body.content || body.referenceText || body.fileText || '').trim();
return [{ json: { body, extractedText: text, extractedFilename: String(body.title || body.filename || 'pasted-text.txt'), extractedSourceType: String(body.sourceType || 'text') } }];

const meta = $('Detect Upload Mode').first().json;
const body = meta.body || {};
const response = $input.first().json || {};
const text = String(response.text || response.content || response.extractedText || response.data?.text || '').trim();
if (!text) throw new Error('File extract service did not return text. Expected response.text.');
return [{ json: {
  body,
  extractedText: text,
  extractedFilename: response.filename || meta.filename || body.title || 'uploaded',
  extractedSourceType: meta.extension || 'file'
} }];

const input = $input.first().json;
const body = input.body || {};
const text = String(input.extractedText || '').trim();
if (!text) throw new Error('Missing text after upload normalization.');
const userId = String(body.userId || 'anonymous');
const title = String(body.title || input.extractedFilename || 'Untitled knowledge');
const documentId = String(body.documentId || `doc_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`);
const cleanText = text
  .replace(/\u0000/g, '')
  .replace(/\r\n/g, '\n')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();
return [{ json: {
  userId,
  documentId,
  title,
  category: String(body.category || 'general'),
  ageRange: String(body.ageRange || ''),
  visibility: String(body.visibility || 'private'),
  sourceType: String(body.sourceType || input.extractedSourceType || 'text'),
  sourceUrl: String(body.sourceUrl || ''),
  filename: String(input.extractedFilename || ''),
  cleanText
} }];

const source = $input.first().json;
const text = source.cleanText;
const chunkSize = 700;
const overlap = 100;
const chunks = [];
let start = 0;
let index = 0;
while (start < text.length) {
  const end = Math.min(text.length, start + chunkSize);
  const chunk = text.slice(start, end).trim();
  if (chunk.length >= 30) {
    chunks.push({
      chunkId: `${source.documentId}_chunk_${String(index + 1).padStart(4, '0')}`,
      chunkIndex: index,
      text: chunk,
      metadata: {
        userId: source.userId,
        documentId: source.documentId,
        title: source.title,
        category: source.category,
        ageRange: source.ageRange,
        visibility: source.visibility,
        sourceType: source.sourceType,
        sourceUrl: source.sourceUrl,
        filename: source.filename,
        createdAt: new Date().toISOString()
      }
    });
    index += 1;
  }
  if (end === text.length) break;
  start = Math.max(0, end - overlap);
}
if (!chunks.length) throw new Error('No valid chunks were produced from the input text.');
return chunks.map((chunk) => ({ json: chunk }));

const original = $('Chunk Text').all();
const embeddings = $input.all();
const points = embeddings.map((item, index) => {
  const source = original[index]?.json;
  const response = item.json || {};
  const vector = response.embedding || response.data?.[0]?.embedding || response.vector;
  if (!Array.isArray(vector)) throw new Error(`Embedding response did not contain a vector for chunk ${source?.chunkId || index}`);
  return {
    id: source.chunkId,
    vector,
    payload: {
      text: source.text,
      chunkIndex: source.chunkIndex,
      ...source.metadata
    }
  };
});
return [{ json: {
  points,
  documentId: original[0]?.json?.metadata?.documentId,
  chunkCount: points.length,
  collection: $env.QDRANT_COLLECTION || 'picturebook_knowledge'
} }];

const prepared = $('Build Qdrant Points').first().json;
const norm = $('Normalize Knowledge').first().json;
const meta = $('Detect Upload Mode').first().json;
const body = meta.body || {};
return [{ json: {
  success: true,
  documentId: prepared.documentId,
  chunkCount: prepared.chunkCount,
  collection: prepared.collection,
  _meta: {
    documentId: prepared.documentId,
    title: norm.title,
    category: norm.category,
    ageRange: norm.ageRange,
    sourceType: norm.sourceType,
    filename: norm.filename,
    chunkCount: prepared.chunkCount,
    uploadedBy: norm.userId,
    uploaderName: String(body.uploaderName || body.userName || ''),
    qdrantCollection: prepared.collection
  }
} }];
